use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn check(dir:&Path){let v=read(dir.join("exit.json"));assert_eq!(v["success"],true);assert_eq!(v["returncode"],0);for stream in ["stdout","stderr"]{assert_eq!(hash(dir.join(format!("{stream}.log"))),v[format!("{stream}_sha256")].as_str().unwrap());}}
fn main(){let root=Path::new("/tmp/zopro-serial-fft-leaves");let config=read(root.join("perf-plan.json"));let report=read(root.join("perf/result.json"));assert_eq!(report["status"],"complete");assert_eq!(report["distinct_verified_exports"],219);assert_eq!(config["pins"].as_object().unwrap().len(),460);let preflight=read(root.join("preflight/result.json"));assert_eq!(preflight["status"],"complete");assert_eq!(preflight["steps"].as_array().unwrap().len(),38);for name in preflight["steps"].as_array().unwrap(){let name=name.as_str().unwrap();let dir=root.join("preflight").join(name);check(&dir);if name.ends_with("-verify"){assert!(fs::read_to_string(dir.join("stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));}}
let raw=read(root.join("perf/rows.json"));let rows=raw.as_array().unwrap();assert_eq!(rows.len(),219);let mut sdk=0usize;let mut profiles=0usize;let mut samples=0u64;let mut latency=0usize;for r in rows{let phase=r["phase"].as_str().unwrap();let name=r["case"].as_str().unwrap();let variant=r["variant"].as_str().unwrap();let b=r["block"].as_u64().unwrap();let dir=root.join("perf").join(phase).join(format!("b{b}")).join(name).join(variant);check(&dir.join("run"));check(&dir.join("verify"));assert!(fs::read_to_string(dir.join("verify/stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));assert_eq!(r["summary"]["priming"],3);assert_eq!(r["summary"]["workers"],if name=="1x2-w16"{16}else{32});sdk+=r["samples_ms"].as_array().unwrap().len()+3;if phase=="profile"{check(&dir.join("symbols"));assert_eq!(r["profile"]["lost_records"],0);assert_eq!(r["profile"]["sampled_pids"].as_array().unwrap().len(),1);samples+=r["profile"]["samples"].as_u64().unwrap();profiles+=1;}else{assert_eq!(phase,"latency");latency+=1;}}
assert_eq!(sdk,9120);assert_eq!(profiles,9);assert_eq!(latency,210);assert_eq!(samples,300972);
let template=read(root.join("all-nine-template.json"));let fixture:BTreeMap<String,String>=template["cases"].as_array().unwrap().iter().map(|c|(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap().to_str().unwrap().into(),c["public_sha256"].as_str().unwrap().into())).collect();let prior:BTreeSet<String>=serde_json::from_value(template["prior_proof_sha256"].clone()).unwrap();assert_eq!(prior.len(),3045);let mut inventory=BTreeMap::<String,String>::new();for(name,digest)in read(root.join("preflight-proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(name),digest.as_str().unwrap());inventory.insert(name.clone(),digest.as_str().unwrap().into());}for(name,digest)in read(root.join("perf/proof-inventory.json")).as_object().unwrap(){let path=root.join("perf").join(name);assert_eq!(hash(&path),digest.as_str().unwrap());inventory.insert(path.to_str().unwrap().into(),digest.as_str().unwrap().into());}assert_eq!(inventory.len(),474);let mut unique=BTreeSet::new();for(name,digest)in &inventory{let path=Path::new(name);if path.extension().is_some_and(|e|e=="proof"){assert!(!prior.contains(digest));assert!(unique.insert(digest.to_owned()));assert!(inventory.contains_key(path.with_extension("public").to_str().unwrap()));}else{assert_eq!(path.extension().unwrap(),"public");let stem=path.parent().unwrap().file_name().unwrap().to_str().unwrap();assert_eq!(&fixture[stem],digest);}}assert_eq!(unique.len(),237);
for name in ["core-off","core-on"]{let text=fs::read_to_string(root.join("native-v2").join(name).join("stdout.log")).unwrap();assert!(text.contains("112 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));}assert_eq!(read(root.join("native-v2/result.json"))["status"],"complete");assert_eq!(read(root.join("source-audit.json"))["original_off_body_recovered"],true);let pilot=read(root.join("pilot-result.json"));assert_eq!(pilot["performance_gate_passed"],false);let failures=pilot["failed_checks"].as_array().unwrap();assert_eq!(failures.len(),1);assert!(failures[0].as_str().unwrap().starts_with("1x2-w16: OFF calibration factor "));
let out=json!({"status":"closed; positive32worker signal, overall screen unqualified because physical16 control calibration failed","performance_gate_passed":false,"all32worker_conditions_passed":true,"adopted":false,"goal_achieved":false,"sdk_requests":sdk+72,"distinct_gnark_exports":unique.len(),"proof_public_members":inventory.len(),"profiles":profiles,"profile_samples":samples,"lost_records":0,"native_core_off":112,"native_core_on":112,"raw_tests":2,"cubic_tests":6,"field_tests":"unchanged kernels, inherited33; no new field-suite execution claimed","source_pins":173,"performance_pins":460,"prior_identities_before_preflight":3045,"failed_checks":pilot["failed_checks"],"original8_aggregate":pilot["original8_aggregate"],"source_audit":read(root.join("source-audit.json")),"initial_failure":read(root.join("failure-v1/review.json")),"scope":"All nine SDK shapes at32 plus physical16primary, complete warm solving/randomness/proving/internal verification/serialization; load and primes excluded. Small kernel/pool tests do not prove concurrent wholeSDK behavior or memory pressure feasibility.","decision":"Preserve promising candidate and complete data; do not adopt or rerun unchanged. The failed control calibration remains failed. Need distinguish16worker measurement variability and qualify compatibility/resources before any future promotion.","limits":"No new portable, pressure, concurrent SDK, large-circuit, C7a or Aeglos qualification/comparison. RSS includes whole process. Sample shares are not removable wall time. Historical M5 references, not new M5 runs. All8 tenfold goal remains unmet.","owned_aws_resources":0});
for(name,value)in [("closeout.json",out),("proof-inventory.json",json!(inventory))]{fs::write(root.join(name),format!("{}\n",serde_json::to_string_pretty(&value).unwrap())).unwrap();}println!("CLOSED_VERIFIED SDK{} EXPORTS237 MEMBERS474 PROFILES9 SAMPLES{samples}",sdk+72);}
